// Full ordered GP0 command ledger, source r0 (claude-einhander). See scene_ledger.r0.h.
// r1 (2026-11-14): ADDITIVE revision of r0 9614a6a8: includes scene_ledger.r1.h and appends scene_ledger_display_hazard.
// SOURCE ONLY: not compiled, not run, not linked. C++17, no allocation, no I/O, no SDK/GL.
// scene_ledger_native_unpack.inc is GENERATED by build_scene_ledger_fixture.r0.py from raw-pinned gpu.c
// 3d8b5d3e and gpu_gl_renderer.c b41b7ab5 (CRLF->LF, exact anchored lines). It provides, in namespace
// scene_ledger_native, the native sign_extend, parse_vertex and gp0_command_word_count verbatim, and thin
// wrappers around the verbatim decode lines of fill, VRAM->VRAM copy, CPU->VRAM, VRAM->CPU, the two variable
// rect sizes, the polygon tpage mask, the CLUT position and the renderer's texture page base/depth.
#include "scene_ledger.r1.h"
#include <atomic>
#include <cstring>
#include "scene_ledger_native_unpack.inc"

namespace {
namespace nat = scene_ledger_native;
constexpr uint32_t kNoIndex = 0xFFFFFFFFu;

std::atomic<uint32_t> owner{0};
std::atomic<uint64_t> foreign{0};   // mutating calls with a foreign token (any thread may increment)
std::atomic<uint64_t> external{0};  // VRAM writes outside GP0 (any thread may increment)
// Owner-thread state below. A foreign caller never touches it.
bool initialized;
uint32_t last_generation;
uint32_t armed_frame;
uint64_t foreign_at_arm, external_at_arm;
bool last_opens_body;               // ARMED: last observed command may open a CPU->VRAM or polyline body
SceneLedgerHeader hdr;
SceneLedgerEntry entries[SCENE_LEDGER_CAPACITY];

int guard_read(uint32_t token) {
    const uint32_t bound = owner.load(std::memory_order_acquire);
    if (!bound) return LEDGER_BAD_STATE;
    return token == bound ? LEDGER_OK : LEDGER_WRONG_THREAD;
}
// Mutating entry points: a foreign token only increments the atomic counter, read at sealing and every read.
int guard_mutate(uint32_t token) {
    const int e = guard_read(token);
    if (e == LEDGER_WRONG_THREAD) foreign.fetch_add(1, std::memory_order_relaxed);
    return e;
}

uint32_t fnv(uint32_t h, uint32_t w) {
    for (int i = 0; i < 4; ++i) { h ^= (w >> (i * 8)) & 255u; h *= 16777619u; }
    return h;
}
uint32_t state_hash(const SceneLedgerState &s) {
    uint32_t h = 2166136261u;
    h = fnv(h, s.texture_window);
    h = fnv(h, uint32_t(s.draw_offset_x));
    h = fnv(h, uint32_t(s.draw_offset_y));
    h = fnv(h, uint32_t(s.draw_left) | (uint32_t(s.draw_top) << 16));
    h = fnv(h, uint32_t(s.draw_right) | (uint32_t(s.draw_bottom) << 16));
    h = fnv(h, uint32_t(s.texpage) | (uint32_t(s.set_mask) << 16) | (uint32_t(s.check_mask) << 24));
    h = fnv(h, uint32_t(s.native_screen_mapping) | (uint32_t(s.display_known) << 8));
    h = fnv(h, uint32_t(s.display_x));
    h = fnv(h, uint32_t(s.display_y));
    h = fnv(h, uint32_t(s.display_w));
    h = fnv(h, uint32_t(s.display_h));
    return h;
}

bool empty(const LedgerRect &r) { return r.x0 >= r.x1 || r.y0 >= r.y1; }
bool intersects(const LedgerRect &a, const LedgerRect &b) {
    return !empty(a) && !empty(b) && a.x0 < b.x1 && b.x0 < a.x1 && a.y0 < b.y1 && b.y0 < a.y1;
}
bool any_intersect(const LedgerRect *a, int na, const LedgerRect *b, int nb) {
    for (int i = 0; i < na; ++i)
        for (int j = 0; j < nb; ++j)
            if (intersects(a[i], b[j])) return true;
    return false;
}
// VRAM is 1024 x 512 halfwords and every native transfer/sample wraps. x/y reduce modulo 1024/512; w/h clip
// to full coverage; a rect crossing the right or bottom edge becomes up to four half-open pieces. Used as a
// conservative superset for draws too (a clipped write is inside its wrapped pieces).
int split_wrap(int64_t x, int64_t y, int64_t w, int64_t h, LedgerRect *out) {
    if (w <= 0 || h <= 0) return 0;
    if (w > 1024) w = 1024;
    if (h > 512) h = 512;
    x = ((x % 1024) + 1024) % 1024;
    y = ((y % 512) + 512) % 512;
    int64_t xs[2][2] = {{x, x + w}, {0, 0}}, ys[2][2] = {{y, y + h}, {0, 0}};
    int nx = 1, ny = 1;
    if (x + w > 1024) { xs[0][1] = 1024; xs[1][1] = x + w - 1024; nx = 2; }
    if (y + h > 512) { ys[0][1] = 512; ys[1][1] = y + h - 512; ny = 2; }
    int n = 0;
    for (int j = 0; j < ny; ++j)
        for (int i = 0; i < nx; ++i)
            out[n++] = LedgerRect{int32_t(xs[i][0]), int32_t(ys[j][0]), int32_t(xs[i][1]), int32_t(ys[j][1])};
    return n;
}
int split_rect(const LedgerRect &r, LedgerRect *out) {
    return empty(r) ? 0 : split_wrap(r.x0, r.y0, int64_t(r.x1) - r.x0, int64_t(r.y1) - r.y0, out);
}
LedgerRect union_of(const LedgerRect *p, int n) {
    if (n <= 0) return LedgerRect{0, 0, 0, 0};
    LedgerRect u = p[0];
    for (int i = 1; i < n; ++i) {
        if (p[i].x0 < u.x0) u.x0 = p[i].x0;
        if (p[i].y0 < u.y0) u.y0 = p[i].y0;
        if (p[i].x1 > u.x1) u.x1 = p[i].x1;
        if (p[i].y1 > u.y1) u.y1 = p[i].y1;
    }
    return u;
}
// Half-open primitive extent (vertex + draw offset, int64) clamped to the inclusive native drawing area, which
// converts to half-open exactly once here. left > right (or top > bottom) gives an empty result.
LedgerRect clamp_draw(int64_t x0, int64_t y0, int64_t x1, int64_t y1, const SceneLedgerState &s) {
    const int64_t l = s.draw_left, t = s.draw_top, r = int64_t(s.draw_right) + 1, b = int64_t(s.draw_bottom) + 1;
    if (x0 < l) x0 = l;
    if (y0 < t) y0 = t;
    if (x1 > r) x1 = r;
    if (y1 > b) y1 = b;
    if (x0 >= x1 || y0 >= y1) return LedgerRect{0, 0, 0, 0};
    return LedgerRect{int32_t(x0), int32_t(y0), int32_t(x1), int32_t(y1)};
}
// Texture page (renderer base/depth lines) and CLUT row (gpu.c lines) of a tpage/clut pair, wrap-split.
void tex_pieces(uint16_t tpage, uint16_t clut, LedgerRect *page, int *np, LedgerRect *cl, int *nc) {
    int bx = 0, by = 0, depth = 0, cx = 0, cy = 0;
    nat::page_unpack(tpage, &bx, &by, &depth);
    nat::clut_unpack(clut, &cx, &cy);
    *np = split_wrap(bx, by, int64_t(64) << depth, 256, page);           // 4/8/15 bpp: 64/128/256 halfwords
    *nc = split_wrap(cx, cy, depth == 0 ? 16 : depth == 1 ? 256 : 0, 1, cl);  // 15 bpp has no CLUT
}

bool opens_body(uint8_t op) { return (op >= 0xA0 && op <= 0xBF) || nat::gp0_command_word_count(op) < 0; }

void add_display(const SceneLedgerState &s) {
    if (!s.display_known || s.display_w < 0 || s.display_h < 0) { hdr.incomplete_mask |= LI_DISPLAY_UNKNOWN; return; }
    const int64_t x1 = int64_t(s.display_x) + s.display_w, y1 = int64_t(s.display_y) + s.display_h;
    if (x1 > INT32_MAX || y1 > INT32_MAX) { hdr.incomplete_mask |= LI_DISPLAY_UNKNOWN; return; }
    const LedgerRect d{s.display_x, s.display_y, int32_t(x1), int32_t(y1)};
    for (uint32_t i = 0; i < hdr.display_count; ++i)
        if (!std::memcmp(&hdr.display[i], &d, sizeof d)) return;
    if (hdr.display_count == uint32_t(SCENE_LEDGER_MAX_DISPLAY)) { hdr.incomplete_mask |= LI_DISPLAY_OVERFLOW; return; }
    hdr.display[hdr.display_count++] = d;
}

void store(const SceneLedgerEntry &e) {
    if (hdr.entry_count == uint32_t(SCENE_LEDGER_CAPACITY)) { ++hdr.overflow; hdr.incomplete_mask |= LI_OVERFLOW; return; }
    entries[hdr.entry_count++] = e;
}
void mark_malformed(SceneLedgerEntry &e) {
    ++hdr.malformed;
    hdr.incomplete_mask |= LI_MALFORMED;
    e.flags = uint16_t(e.flags | LF_MALFORMED | LF_UNKNOWN_FOOTPRINT);
    e.flags = uint16_t(e.flags & ~LF_CAPTURED_TEXTURED);
}
uint8_t class_of(uint8_t op) {
    if (op == 0x02) return LC_FILL;
    if (op >= 0x20 && op <= 0x3F) return LC_POLYGON;
    if ((op >= 0x40 && op <= 0x47) || (op >= 0x50 && op <= 0x57)) return LC_LINE;
    if ((op >= 0x48 && op <= 0x4F) || (op >= 0x58 && op <= 0x5F)) return LC_POLYLINE;
    if (op >= 0x60 && op <= 0x7F) return LC_RECT;
    if (op >= 0x80 && op <= 0x9F) return LC_COPY;
    if (op >= 0xA0 && op <= 0xBF) return LC_WRITE;
    if (op >= 0xC0 && op <= 0xDF) return LC_READ;
    if (op >= 0xE1 && op <= 0xE6) return LC_STATE;
    if (op == 0x1F || nat::gp0_command_word_count(op) == 0) return LC_OTHER;  // native halts on both
    return LC_NOP;  // 0x00, 0x01, 0x03-0x1E, 0xE0, 0xE7-0xEF, 0xFF
}

// Footprint of a well-formed draw (polygon / line / rect). Sets LF_UNKNOWN_FOOTPRINT (and LI_MAPPING) when the
// native screen mapping is not identity, because widescreen / 2D / geometry transforms then move the write.
void draw_footprint(SceneLedgerEntry &e, const uint32_t *w, const SceneLedgerState &s) {
    const uint8_t op = e.op;
    int64_t minx = 0, miny = 0, maxx = 0, maxy = 0;   // half-open after the +1 below
    if (e.cls == LC_POLYGON) {
        const bool shaded = (op & 0x10) != 0, textured = (op & 0x04) != 0, quad = (op & 0x08) != 0;
        const int verts = quad ? 4 : 3, stride = 1 + (textured ? 1 : 0) + (shaded ? 1 : 0);
        int32_t vx[4] = {0, 0, 0, 0}, vy[4] = {0, 0, 0, 0};
        for (int i = 0; i < verts; ++i) nat::parse_vertex(w[1 + i * stride], &vx[i], &vy[i]);
        const int tri[2][3] = {{0, 1, 2}, {2, 1, 3}};   // native quad split, as scene_capture indices
        for (int t = 0; t < verts - 2; ++t) {
            int32_t lx = vx[tri[t][0]], hx = lx, ly = vy[tri[t][0]], hy = ly;
            for (int j = 1; j < 3; ++j) {
                const int k = tri[t][j];
                if (vx[k] < lx) lx = vx[k];
                if (vx[k] > hx) hx = vx[k];
                if (vy[k] < ly) ly = vy[k];
                if (vy[k] > hy) hy = vy[k];
            }
            if (hx - lx > 1023 || hy - ly > 511) e.flags = uint16_t(e.flags | LF_OVERSIZE);
        }
        minx = maxx = vx[0];
        miny = maxy = vy[0];
        for (int i = 1; i < verts; ++i) {
            if (vx[i] < minx) minx = vx[i];
            if (vx[i] > maxx) maxx = vx[i];
            if (vy[i] < miny) miny = vy[i];
            if (vy[i] > maxy) maxy = vy[i];
        }
        maxx += 1;   // inclusive native extent -> half-open, once
        maxy += 1;
        if (textured) {
            e.flags = uint16_t(e.flags | LF_TEXTURED);
            e.clut = uint16_t(w[2] >> 16);                               // scene_capture.cpp :111
            e.tpage = nat::poly_tpage(uint16_t(w[shaded ? 5 : 4] >> 16));  // word index: scene_capture.cpp :112
        }
    } else if (e.cls == LC_LINE) {
        int32_t x0 = 0, y0 = 0, x1 = 0, y1 = 0;
        nat::parse_vertex(w[1], &x0, &y0);
        nat::parse_vertex(w[op >= 0x50 ? 3 : 2], &x1, &y1);              // gpu.c mono [1],[2]; shaded [1],[3]
        minx = x0 < x1 ? x0 : x1;
        maxx = (x0 > x1 ? x0 : x1) + int64_t(1);
        miny = y0 < y1 ? y0 : y1;
        maxy = (y0 > y1 ? y0 : y1) + int64_t(1);
    } else {  // LC_RECT
        int32_t x = 0, y = 0;
        int rw = 0, rh = 0;
        nat::parse_vertex(w[1], &x, &y);
        if (op <= 0x63) nat::mono_rect_size(w, &rw, &rh);
        else if (op <= 0x67) nat::textured_rect_size(w, &rw, &rh);
        else if (op <= 0x6F) rw = rh = 1;      // gpu.c: 1x1 dot sizes are literals
        else if (op <= 0x77) rw = rh = 8;
        else rw = rh = 16;
        minx = x;
        miny = y;
        maxx = int64_t(x) + rw;
        maxy = int64_t(y) + rh;
        if (op & 0x04) {
            e.flags = uint16_t(e.flags | LF_TEXTURED);
            e.clut = uint16_t(w[2] >> 16);    // gpu.c textured rect / dot / 8x8 / 16x16: gp0_cmd_buf[2] >> 16
            e.tpage = uint16_t(s.texpage & 0x1FF);   // current_texpage() in force (poly latch included)
        }
    }
    e.flags = uint16_t(e.flags | LF_DRAW);
    if (!s.native_screen_mapping) {
        e.flags = uint16_t(e.flags | LF_UNKNOWN_FOOTPRINT);
        hdr.incomplete_mask |= LI_MAPPING;
        ++hdr.mapping_unknown;
        return;
    }
    if (minx >= maxx || miny >= maxy) return;   // zero-size rect: no footprint
    e.bbox = clamp_draw(minx + s.draw_offset_x, miny + s.draw_offset_y, maxx + s.draw_offset_x,
                        maxy + s.draw_offset_y, s);
    e.dst_count = uint8_t(split_rect(e.bbox, e.dst));
}

// Returns true when the command was malformed.
bool record(const uint32_t *w, int n, const SceneLedgerState *s) {
    SceneLedgerEntry e;
    std::memset(&e, 0, sizeof e);
    e.global_index = hdr.command_count++;
    e.textured_index = kNoIndex;
    if (!w || n < 1) {
        e.cls = LC_OTHER;
        mark_malformed(e);
        store(e);
        return true;
    }
    const uint8_t op = uint8_t(w[0] >> 24);
    e.op = op;
    e.cls = class_of(op);
    if (s) {
        e.state_hash = state_hash(*s);
        hdr.final_state_hash = e.state_hash;
        add_display(*s);
    }
    const int native_words = nat::gp0_command_word_count(op);
    if (e.cls == LC_POLYGON && (op & 0x04)) {           // capture parity: ordinal assigned before validation
        e.flags = uint16_t(LF_TEXTURED_POLY | LF_CAPTURED_TEXTURED);
        e.textured_index = hdr.textured_seen++;
    }
    if (e.cls == LC_OTHER) {
        ++hdr.unsupported;
        hdr.incomplete_mask |= LI_UNSUPPORTED;
        e.flags = uint16_t(e.flags | LF_UNKNOWN_FOOTPRINT);
        store(e);
        return false;
    }
    if (e.cls == LC_POLYLINE) {                          // only the header reaches this hook (gpu.c :5506-5520)
        ++hdr.polylines;
        ++hdr.unknown_footprints;
        hdr.incomplete_mask |= LI_UNKNOWN_FOOTPRINT;
        e.flags = uint16_t(e.flags | LF_DRAW | LF_UNKNOWN_FOOTPRINT);
        const bool bad = n != 1;
        if (bad) mark_malformed(e);
        store(e);
        return bad;
    }
    if (n != native_words || !s) {
        mark_malformed(e);
        store(e);
        return true;
    }
    switch (e.cls) {
    case LC_POLYGON: case LC_LINE: case LC_RECT:
        draw_footprint(e, w, *s);
        break;
    case LC_FILL: {
        uint32_t x = 0, y = 0, fw = 0, fh = 0;
        nat::fill_unpack(w, &x, &y, &fw, &fh);           // not clamped to the drawing area (hardware)
        e.dst_count = uint8_t(split_wrap(x, y, fw, fh, e.dst));
        e.flags = uint16_t(e.flags | LF_MUTATES);
        break;
    }
    case LC_COPY: {
        int sx = 0, sy = 0, dx = 0, dy = 0, cw = 0, ch = 0;
        nat::copy_unpack(w, &sx, &sy, &dx, &dy, &cw, &ch);
        e.src_count = uint8_t(split_wrap(sx, sy, cw, ch, e.src));
        e.dst_count = uint8_t(split_wrap(dx, dy, cw, ch, e.dst));
        e.flags = uint16_t(e.flags | LF_MUTATES | LF_READS);
        break;
    }
    case LC_WRITE: {
        int x = 0, y = 0, ww = 0, wh = 0;
        nat::cpu_to_vram_unpack(w, &x, &y, &ww, &wh);
        e.dst_count = uint8_t(split_wrap(x, y, ww, wh, e.dst));
        e.flags = uint16_t(e.flags | LF_MUTATES);
        break;
    }
    case LC_READ: {
        int x = 0, y = 0, rw = 0, rh = 0;
        nat::vram_to_cpu_unpack(w, &x, &y, &rw, &rh);
        e.src_count = uint8_t(split_wrap(x, y, rw, rh, e.src));
        e.flags = uint16_t(e.flags | LF_READS);
        break;
    }
    default:   // LC_NOP, LC_STATE: no footprint
        break;
    }
    if (e.cls == LC_FILL || e.cls == LC_COPY || e.cls == LC_WRITE) e.bbox = union_of(e.dst, e.dst_count);
    if (!e.dst_count && !e.src_count && !(e.flags & LF_UNKNOWN_FOOTPRINT)) e.flags = uint16_t(e.flags | LF_EMPTY);
    store(e);
    return false;
}

void evaluate() {
    const uint64_t f = foreign.load(std::memory_order_acquire) - foreign_at_arm;
    const uint64_t x = external.load(std::memory_order_acquire) - external_at_arm;
    hdr.foreign_calls = f;
    hdr.external_writes = x;
    if (f) hdr.incomplete_mask |= LI_FOREIGN;
    if (x) hdr.incomplete_mask |= LI_EXTERNAL;
    hdr.complete = uint8_t(hdr.sealed && !hdr.incomplete_mask && hdr.entry_count == hdr.command_count);
}

// Identical transitions to scene_capture_tick (v66-r3 :75-86).
void advance(uint32_t frame) {
    if (hdr.mode == LEDGER_ARMED && frame != armed_frame) {
        if (uint32_t(frame - armed_frame) != 1) hdr.incomplete_mask |= LI_FRAME_GAP;
        if (last_opens_body) hdr.incomplete_mask |= LI_OPEN_AT_START;
        hdr.frame = frame;
        hdr.mode = LEDGER_RECORDING;
    } else if (hdr.mode == LEDGER_RECORDING && frame != hdr.frame) {
        if (uint32_t(frame - hdr.frame) != 1) hdr.incomplete_mask |= LI_FRAME_GAP;
        hdr.mode = LEDGER_SEALED;
        hdr.sealed = 1;
        evaluate();
    }
}
void reset_header(uint32_t mode) {
    std::memset(&hdr, 0, sizeof hdr);
    hdr.mode = mode;
}
}  // namespace

extern "C" int scene_ledger_init(uint32_t token, int enabled) {
    if (!token || (enabled != 0 && enabled != 1)) return LEDGER_BAD_ARGUMENT;
    uint32_t expected = 0;
    if (!owner.compare_exchange_strong(expected, token, std::memory_order_acq_rel) && expected != token)
        return LEDGER_WRONG_THREAD;
    if (initialized) return LEDGER_BAD_STATE;
    reset_header(enabled ? LEDGER_IDLE : LEDGER_DISABLED);
    initialized = true;
    return LEDGER_OK;
}
extern "C" int scene_ledger_arm(uint32_t token, uint32_t frame, uint32_t capture_generation, int gp0_open) {
    if (int e = guard_mutate(token)) return e;
    if (!initialized || hdr.mode == LEDGER_DISABLED || hdr.mode == LEDGER_ARMED || hdr.mode == LEDGER_RECORDING)
        return LEDGER_BAD_STATE;
    if (!capture_generation || capture_generation == last_generation || (gp0_open != 0 && gp0_open != 1))
        return LEDGER_BAD_ARGUMENT;
    reset_header(LEDGER_ARMED);
    hdr.generation = last_generation = capture_generation;
    hdr.owner_token = token;
    if (gp0_open) hdr.incomplete_mask |= LI_ARM_OPEN;
    armed_frame = frame;
    last_opens_body = false;
    foreign_at_arm = foreign.load(std::memory_order_acquire);
    external_at_arm = external.load(std::memory_order_acquire);
    return LEDGER_OK;
}
extern "C" int scene_ledger_cancel(uint32_t token) {
    if (int e = guard_mutate(token)) return e;
    if (!initialized || hdr.mode == LEDGER_DISABLED) return LEDGER_BAD_STATE;
    reset_header(LEDGER_IDLE);
    return LEDGER_OK;
}
extern "C" int scene_ledger_tick(uint32_t token, uint32_t frame) {
    if (int e = guard_mutate(token)) return e;
    advance(frame);
    return LEDGER_OK;
}
extern "C" int scene_ledger_command(uint32_t token, uint32_t frame, const uint32_t *w, int n,
                                    const SceneLedgerState *s) {
    if (int e = guard_mutate(token)) return e;
    advance(frame);
    if (hdr.mode == LEDGER_ARMED) {   // outside the interval: only remember whether a body may be open
        last_opens_body = !w || n < 1 || opens_body(uint8_t(w[0] >> 24));
        return LEDGER_OK;
    }
    if (hdr.mode != LEDGER_RECORDING) return LEDGER_OK;
    return record(w, n, s) ? LEDGER_BAD_ARGUMENT : LEDGER_OK;
}
extern "C" void scene_ledger_note_external_vram_write(void) {
    external.fetch_add(1, std::memory_order_relaxed);
}
extern "C" int scene_ledger_header(uint32_t token, SceneLedgerHeader *out) {
    if (int e = guard_read(token)) return e;
    if (!out) return LEDGER_BAD_ARGUMENT;
    if (hdr.mode == LEDGER_SEALED) evaluate();
    *out = hdr;
    return LEDGER_OK;
}
extern "C" int scene_ledger_get(uint32_t token, uint32_t index, uint32_t generation, SceneLedgerEntry *out) {
    if (int e = guard_read(token)) return e;
    if (!out) return LEDGER_BAD_ARGUMENT;
    std::memset(out, 0, sizeof *out);
    if (hdr.mode == LEDGER_SEALED) evaluate();
    if (hdr.mode != LEDGER_SEALED || !hdr.complete || generation != hdr.generation || index >= hdr.entry_count)
        return LEDGER_BAD_STATE;
    *out = entries[index];
    return LEDGER_OK;
}
extern "C" int scene_ledger_policy(uint32_t token, uint32_t generation, const uint32_t *t, uint32_t n,
                                   SceneLedgerVerdict *out) {
    if (int e = guard_read(token)) return e;
    if (!out || (n && !t)) return LEDGER_BAD_ARGUMENT;
    *out = SceneLedgerVerdict{LP_NATIVE_INCOMPLETE, kNoIndex, kNoIndex};
    if (hdr.mode == LEDGER_SEALED) evaluate();
    if (hdr.mode != LEDGER_SEALED || !hdr.complete || generation != hdr.generation) return LEDGER_OK;
    auto verdict = [&](uint32_t v, uint32_t entry, uint32_t ref) { *out = SceneLedgerVerdict{v, entry, ref}; };
    if (n == 0) { verdict(LP_TRANSPORT_OK, kNoIndex, kNoIndex); return LEDGER_OK; }
    if (n > uint32_t(SCENE_LEDGER_CAPACITY)) { verdict(LP_NATIVE_BAD_REF, kNoIndex, kNoIndex); return LEDGER_OK; }
    static uint32_t ref_entry[SCENE_LEDGER_CAPACITY];   // owner thread only
    for (uint32_t r = 0; r < n; ++r) {
        uint32_t found = kNoIndex;
        for (uint32_t j = 0; j < hdr.entry_count && found == kNoIndex; ++j)
            if ((entries[j].flags & LF_CAPTURED_TEXTURED) && entries[j].textured_index == t[r]) found = j;
        if (found == kNoIndex) { verdict(LP_NATIVE_BAD_REF, kNoIndex, r); return LEDGER_OK; }
        for (uint32_t q = 0; q < r; ++q)
            if (ref_entry[q] == found) { verdict(LP_NATIVE_BAD_REF, found, r); return LEDGER_OK; }
        ref_entry[r] = found;
    }
    LedgerRect disp[SCENE_LEDGER_MAX_DISPLAY * SCENE_LEDGER_MAX_PIECES];
    int nd = 0;
    for (uint32_t i = 0; i < hdr.display_count; ++i) nd += split_rect(hdr.display[i], disp + nd);
    // 1. A fill/copy/write into a displayed framebuffer area.
    for (uint32_t j = 0; j < hdr.entry_count; ++j)
        if ((entries[j].flags & LF_MUTATES) && any_intersect(entries[j].dst, entries[j].dst_count, disp, nd)) {
            verdict(LP_NATIVE_FB_MUTATION, j, kNoIndex);
            return LEDGER_OK;
        }
    for (uint32_t r = 0; r < n; ++r) {
        const SceneLedgerEntry &p = entries[ref_entry[r]];
        LedgerRect tex[2 * SCENE_LEDGER_MAX_PIECES];
        int np = 0, nc = 0;
        tex_pieces(p.tpage, p.clut, tex, &np, tex + SCENE_LEDGER_MAX_PIECES, &nc);
        LedgerRect used[2 * SCENE_LEDGER_MAX_PIECES];   // page pieces then CLUT pieces, contiguous
        int nu = 0;
        for (int i = 0; i < np; ++i) used[nu++] = tex[i];
        for (int i = 0; i < nc; ++i) used[nu++] = tex[SCENE_LEDGER_MAX_PIECES + i];
        // 2. The transported page/CLUT is (part of) a displayed framebuffer.
        if (any_intersect(used, nu, disp, nd)) { verdict(LP_NATIVE_DISPLAY, ref_entry[r], r); return LEDGER_OK; }
        for (uint32_t j = 0; j < hdr.entry_count; ++j) {
            const SceneLedgerEntry &e = entries[j];
            const bool hits = any_intersect(e.dst, e.dst_count, used, nu);
            // 3. Any VRAM mutation of the transported page/CLUT anywhere in the frame (before, between, after).
            if ((e.flags & LF_MUTATES) && hits) { verdict(LP_NATIVE_MUTATION, j, r); return LEDGER_OK; }
            // 4. Any draw (native or transported) writing into the transported page/CLUT: feedback.
            if ((e.flags & LF_DRAW) && hits) { verdict(LP_NATIVE_DRAW_DEST, j, r); return LEDGER_OK; }
            if (j <= ref_entry[r]) continue;
            // 5. After the transported polygon: a VRAM read or textured sample of its (natively suppressed) dst.
            if ((e.flags & LF_READS) && any_intersect(e.src, e.src_count, p.dst, p.dst_count)) {
                verdict(LP_NATIVE_READBACK, j, r);
                return LEDGER_OK;
            }
            if (e.flags & LF_TEXTURED) {
                LedgerRect et[2 * SCENE_LEDGER_MAX_PIECES];
                int ep = 0, ec = 0;
                tex_pieces(e.tpage, e.clut, et, &ep, et + SCENE_LEDGER_MAX_PIECES, &ec);
                if (any_intersect(et, ep, p.dst, p.dst_count) ||
                    any_intersect(et + SCENE_LEDGER_MAX_PIECES, ec, p.dst, p.dst_count)) {
                    verdict(LP_NATIVE_READBACK, j, r);
                    return LEDGER_OK;
                }
            }
        }
    }
    verdict(LP_TRANSPORT_OK, kNoIndex, kNoIndex);
    return LEDGER_OK;
}
// r1 (additive): display hazard of an explicit target rect; see scene_ledger.r1.h. Everything above is r0.
extern "C" int scene_ledger_display_hazard(uint32_t token, uint32_t generation, const uint32_t *t, uint32_t n,
                                           const int32_t rect[4], SceneLedgerVerdict *out) {
    if (int e = guard_read(token)) return e;
    if (!out || !rect || (n && !t) || rect[2] <= 0 || rect[3] <= 0) return LEDGER_BAD_ARGUMENT;
    *out = SceneLedgerVerdict{LP_NATIVE_INCOMPLETE, kNoIndex, kNoIndex};
    if (hdr.mode == LEDGER_SEALED) evaluate();
    if (hdr.mode != LEDGER_SEALED || !hdr.complete || generation != hdr.generation) return LEDGER_OK;
    auto verdict = [&](uint32_t v, uint32_t entry, uint32_t ref) { *out = SceneLedgerVerdict{v, entry, ref}; };
    if (n > uint32_t(SCENE_LEDGER_CAPACITY)) { verdict(LP_NATIVE_BAD_REF, kNoIndex, kNoIndex); return LEDGER_OK; }
    static uint32_t ref_entry[SCENE_LEDGER_CAPACITY];   // owner thread only
    for (uint32_t r = 0; r < n; ++r) {                   // the same reference rules as scene_ledger_policy
        uint32_t found = kNoIndex;
        for (uint32_t j = 0; j < hdr.entry_count && found == kNoIndex; ++j)
            if ((entries[j].flags & LF_CAPTURED_TEXTURED) && entries[j].textured_index == t[r]) found = j;
        if (found == kNoIndex) { verdict(LP_NATIVE_BAD_REF, kNoIndex, r); return LEDGER_OK; }
        for (uint32_t q = 0; q < r; ++q)
            if (ref_entry[q] == found) { verdict(LP_NATIVE_BAD_REF, found, r); return LEDGER_OK; }
        ref_entry[r] = found;
    }
    LedgerRect target[SCENE_LEDGER_MAX_PIECES];
    const int nt = split_wrap(rect[0], rect[1], rect[2], rect[3], target);
    LedgerRect disp[SCENE_LEDGER_MAX_DISPLAY * SCENE_LEDGER_MAX_PIECES];
    int nd = 0;
    for (uint32_t i = 0; i < hdr.display_count; ++i) nd += split_rect(hdr.display[i], disp + nd);
    // 1. The target overlaps an area displayed during the interval: not a hidden (back) buffer.
    if (any_intersect(target, nt, disp, nd)) { verdict(LP_NATIVE_DISPLAY, kNoIndex, kNoIndex); return LEDGER_OK; }
    // 2. A transported page or CLUT overlaps the target.
    for (uint32_t r = 0; r < n; ++r) {
        const SceneLedgerEntry &p = entries[ref_entry[r]];
        LedgerRect tex[2 * SCENE_LEDGER_MAX_PIECES];
        int np = 0, nc = 0;
        tex_pieces(p.tpage, p.clut, tex, &np, tex + SCENE_LEDGER_MAX_PIECES, &nc);
        if (any_intersect(tex, np, target, nt) || any_intersect(tex + SCENE_LEDGER_MAX_PIECES, nc, target, nt)) {
            verdict(LP_NATIVE_DISPLAY, ref_entry[r], r);
            return LEDGER_OK;
        }
    }
    verdict(LP_TRANSPORT_OK, kNoIndex, kNoIndex);
    return LEDGER_OK;
}
